const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a MultiPolygon that roughly covers Wales, central, and southern England.
  const aoi = ee.Geometry.MultiPolygon([
    // Wales
    [
      [-5.36, 53.43], [-3.18, 53.43], [-2.5, 51.5], [-4.2, 51.5], [-5.36, 53.43]
    ],
    // Central and Southern England
    [
      [-3.0, 53.0], [1.7, 53.0], [1.7, 50.5], [-3.0, 50.5], [-3.0, 53.0]
    ]
  ]);

  const startDate = '2024-01-02';
  const endDate = '2024-01-03';

  // 2. Data Acquisition & Check
  const gpmCollection = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(startDate, endDate)
    .filterBounds(aoi)
    .select('precipitationCal');

  const imageCount = gpmCollection.size().getInfo();
  if (imageCount === 0) {
    console.log('No GPM images found for the specified date and location.');
    console.log('A'); // C1 is not the final answer as this is a known data gap for GPM IMERG V06.
    return;
  }

  console.log(`Found ${imageCount} GPM images for Jan 2, 2024.`);

  // 3. Processing
  // GPM provides precipitation rate in mm/hr for each 30-minute interval.
  // To get the total daily precipitation, sum all rates and multiply by 0.5 hours.
  const totalPrecipitation = gpmCollection.sum().multiply(0.5);

  // 4. Calculation
  // Find the maximum precipitation value within the defined area.
  // Using a coarser scale (5000m) to ensure the calculation completes over the large area.
  const maxPrecip = totalPrecipitation.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: aoi,
    scale: 5000,
    maxPixels: 1e9
  });

  const maxVal = maxPrecip.get('precipitationCal').getInfo();

  // 5. Validation & Final Answer
  if (maxVal === null || typeof maxVal === 'undefined') {
    console.log('Calculation failed: could not determine maximum precipitation.');
    console.log('C3');
    return;
  }

  console.log(`Maximum precipitation on Jan 2, 2024: ${maxVal.toFixed(2)} mm`);

  if (maxVal >= 35) {
    console.log('Evidence: The maximum rainfall was above the 35 mm threshold.');
    console.log('A');
  } else {
    console.log('Evidence: The maximum rainfall was below the 35 mm threshold.');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('D');
});
